const CFG = window.DEFAS || {};
/* Beni hatırla: işaretliyse oturum bu cihazda kalıcı (localStorage), değilse tarayıcı kapanınca kapanır (sessionStorage) */
const LS={get:k=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch{}}};
const remOn=()=>LS.get('defas-rem')!=='0';
const AUTHSTORE={getItem:k=>{try{return(remOn()?localStorage:sessionStorage).getItem(k)}catch{return null}},setItem:(k,v)=>{try{(remOn()?localStorage:sessionStorage).setItem(k,v)}catch{}},removeItem:k=>{try{localStorage.removeItem(k)}catch{}try{sessionStorage.removeItem(k)}catch{}}};
const sb = CFG.url && window.supabase ? supabase.createClient(CFG.url, CFG.anon, {auth:{storage:AUTHSTORE,persistSession:true,autoRefreshToken:true}}) : null;

/* ---------- ikonlar ---------- */
const IC={home:'M3 11l9-8 9 8M5 10v10h14V10',check:'M4 12l5 5L20 6',folder:'M3 6h6l2 3h10v10H3z',clock:'M12 21a9 9 0 100-18 9 9 0 000 18zM12 7v5l3 2',gear:'M12 15a3 3 0 100-6 3 3 0 000 6zM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',bell:'M6 16V10a6 6 0 1112 0v6l2 2H4zM10 21h4',more:'M5 12h.01M12 12h.01M19 12h.01',plus:'M12 5v14M5 12h14',down:'M12 4v12M6 11l6 6 6-6M4 21h16',up:'M12 16V4M6 9l6-6 6 6M4 21h16',users:'M16 20v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2M9 10a4 4 0 100-8 4 4 0 000 8zM22 20v-2a4 4 0 00-3-3.9M16 2.1a4 4 0 010 7.8',out:'M9 21H4V3h5M16 17l5-5-5-5M21 12H9',doc:'M6 2h9l5 5v15H6zM14 2v6h6M9 13h8M9 17h8',shield:'M12 2l8 3v6c0 5-3.5 9-8 11-4.5-2-8-6-8-11V5zM9 12l2 2 4-4',cal:'M3 5h18v16H3zM3 10h18M8 2v5M16 2v5',qr:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h3v3h-3zM18 18h3v3h-3zM14 20h2M20 14v2',left:'M15 6l-6 6 6 6',right:'M9 6l6 6-6 6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM12 15a3 3 0 100-6 3 3 0 000 6z',x:'M6 6l12 12M18 6L6 18',warn:'M12 3l10 18H2zM12 10v4M12 17h.01',refresh:'M20 11a8 8 0 10-2.3 5.7M20 4v7h-7',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',chart:'M4 20V10M10 20V4M16 20v-7M22 20H2',cam:'M3 8h4l2-3h6l2 3h4v12H3zM12 17a4 4 0 100-8 4 4 0 000 8z'};
const ic=(k,s=20)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${IC[k]}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];

/* ---------- tarih / saat (Türkiye UTC+3) ---------- */
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const pd=s=>{const[a,b,c]=s.slice(0,10).split('-').map(Number);return new Date(a,b-1,c)};
const add=(s,n)=>{const d=pd(s);d.setDate(d.getDate()+n);return iso(d)};
const diff=(a,b)=>Math.round((pd(a)-pd(b))/864e5);
let TODAY=iso(new Date());
const ymOf=s=>s.slice(0,7);
const monthDays=m=>{const[y,mo]=m.split('-').map(Number),n=new Date(y,mo,0).getDate();return Array.from({length:n},(_,i)=>`${m}-${String(i+1).padStart(2,'0')}`)};
const addMonth=(m,k)=>{const[y,mo]=m.split('-').map(Number);return iso(new Date(y,mo-1+k,1)).slice(0,7)};
const trD=(s,o={day:'numeric',month:'long'})=>pd(s).toLocaleDateString('tr-TR',o);
const trDY=s=>trD(s,{day:'numeric',month:'long',year:'numeric'});
const trDL=s=>trD(s,{day:'numeric',month:'long',weekday:'long'});
const trM=m=>pd(m+'-01').toLocaleDateString('tr-TR',{month:'long',year:'numeric'});
const dmy=s=>s?s.slice(0,10).split('-').reverse().join('.'):'';
const tm=t=>t?new Date(t).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'}):'';
const hh=t=>t?String(t).slice(0,5):'';
const hrs=m=>(Math.round((m||0)/6)/10).toLocaleString('tr-TR');
const dayStart=d=>`${d}T00:00:00+03:00`;
const WD=['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'];
const dow=s=>(pd(s).getDay()+6)%7+1;
const left=d=>{const n=diff(d,TODAY);return n<0?`${-n} gün geçti`:n===0?'bugün bitiyor':n===1?'yarın bitiyor':`${n} gün kaldı`};
const init=n=>String(n||'?').split(' ').filter(Boolean).slice(0,2).map(w=>w[0]).join('').toLocaleUpperCase('tr');
const norm=s=>String(s??'').toLocaleLowerCase('tr').replace(/\s+/g,' ').trim();

/* ---------- durum ---------- */
const S={flows:[],me:null,people:[],docTypes:[],settings:null,workDays:[],hol:new Map(),notifs:[],projects:[],positions:[],depts:[],view:null};
const D={};            // sayfa verisi önbelleği
const ui={};           // ekran seçimleri
const PEND={};
const CODES={C:['ok','Çalıştı'],S:['info','Sahada'],E:['warn','Eksik kayıt'],D:['bad','Devamsız'],Y:['gray','Yıllık izin'],R:['gray','Raporlu'],U:['gray','Ücretsiz izin'],M:['gray','Mazeret izni'],H:['bad','Hafta tatili kesildi']};
const PERMS={personel:'Personel ve belgeler',puantaj:'Puantaj ve muhasebe',proje:'Proje çalışma listesi',gorev:'Görev yönetimi (kendi birimi)',ayar:'Sistem ayarları'};
const ROLES={gm:'Genel yönetici',mgr:'Birim yöneticisi',w:'Çalışan'};
const STAT={aday:['warn','Aday · belge bekliyor'],aktif:['ok','Aktif'],ayrildi:['gray','Ayrıldı']};
const pill=([c,t])=>`<span class="pill ${c}">${esc(t)}</span>`;
const pp=id=>S.people.find(p=>p.id===id);
const nm=id=>pp(id)?.full_name||'—';
// Yetki grubu: işaretli sekmeler menüyü, sekmelerden çıkan veri yetkileri veritabanı kurallarını belirler (SQL group_perms ile aynı)
const TABS=[['boss','Yönetim özeti','Genel','Patron paneli: bugün, projeler, onaylar, uyarılar (yetkisi olan veriyi görür)'],['home','Ana sayfa','Genel','Kişinin kendi özeti'],['jobs','Görevlerim','Genel','Kendi bakım/görev işleri'],['forms','Formlar','Genel','İzin, avans, araç, kredi kartı formları'],['mytime','Puantajım','Genel','Kendi giriş-çıkış ve saatleri'],['mydocs','Belgelerim','Genel','Kendi belgeleri, sertifika yükleme'],
 ['japp','İş onayı','Bakım ve görevler','Kontrol edeni olduğu işleri onaylar'],['jpanel','Görev paneli','Bakım ve görevler','Biriminin görev özeti'],['tasks','Görevler','Bakım ve görevler','Biriminin görevlerini ekler, düzenler, yönlendirir'],['jrep','Görev raporu','Bakım ve görevler','Biriminin performans raporu'],
 ['today','Yoklama','Personel ve puantaj','Bugün gelen / gelmeyen'],['people','Personel','Personel ve puantaj','Personel kartı, T.C., adres, işe giriş-çıkış'],['matrix','Belge matrisi','Personel ve puantaj','Tüm personelin belge tarihleri'],['expiry','Belge takibi','Personel ve puantaj','Süresi dolan belgeler, belge onayı'],['puantaj','Puantaj','Personel ve puantaj','Tüm puantaj, düzeltme, Excel, FRM-027'],['vehicles','Şirket araçları','Personel ve puantaj','Şirket araçları: plaka, ruhsat, sigorta, kasko'],
 ['plist','Çalışma listesi','Proje','Proje çalışma listesini hazırlar ve yayınlar'],['equip','Ekipmanlar','Depo ve zimmet','Ekipman ekler, zimmetler, iade alır, bakıma gönderir, QR etiket basar'],['settings','Ayarlar','Sistem','Çalışma saatleri, e-posta, belge türleri, onay akışları'],['qrsites','QR noktaları','Sistem','Fabrika kapısı ve şantiye QR kodlarını açar, afiş basar']];
const tabPerms=tabs=>{const T=new Set(tabs||[]),o=[];if(['people','matrix','expiry'].some(k=>T.has(k)))o.push('personel');if(T.has('puantaj'))o.push('puantaj');if(T.has('plist'))o.push('proje');if(T.has('settings'))o.push('ayar');if(T.has('qrsites'))o.push('qr');if(T.has('equip'))o.push('depo');if(['tasks','jpanel','jrep'].some(k=>T.has(k)))o.push('gorev');return o};
const myGroup=()=>S.me&&(S.groups||[]).find(g=>g.id===S.me.group_id);
const can=p=>!!S.me&&(S.me.role==='gm'||(S.me.perms||[]).includes(p)||tabPerms(myGroup()?.tabs).includes(p));
const tabOk=k=>k==='home'||k==='news'||S.me.role==='gm'||!myGroup()||myGroup().tabs.includes(k);
const leads=()=>S.me.role!=='w'||tabOk('today')&&!!myGroup()||can('personel')||can('puantaj')||S.people.some(p=>p.manager_id===S.me.id&&p.status!=='ayrildi');
const wdOf=s=>S.workDays.find(w=>w.dow===dow(s));
const holOf=s=>S.hol.get(s);
const isWork=s=>{const w=wdOf(s),h=holOf(s);return!!(w&&w.start_time)&&(!h||h.half)};

/* ---------- veri ---------- */
const must=r=>{if(r.error)throw new Error(trErr(r.error.message));return r.data};
const rpc=async(f,a)=>must(await sb.rpc(f,a));
function trErr(m){m=String(m||'');if(/JWT|session/i.test(m))return'Oturum süresi doldu, yeniden giriş yapın';if(/Failed to fetch|NetworkError/i.test(m))return'İnternet bağlantısı yok';if(/Invalid login/i.test(m))return'Giriş adı veya şifre hatalı';if(/row-level security|permission denied/i.test(m))return'Bu işlem için yetkiniz yok';return m}
// Proje sıralaması: kodun son 3 hanesi (ardışık numara) küçükten büyüğe · ABC-26-001, ABC-26-002 …
function pno(c){const m=String(c||'').match(/-(\d+)\s*$/);return m?+m[1]:1e9}
function byNo(L){return(L||[]).sort((a,b)=>pno(a.code)-pno(b.code)||String(a.code).localeCompare(String(b.code),'tr'))}
async function all(q){let out=[],i=0;for(;;){const r=must(await q().range(i,i+999));out=out.concat(r);if(r.length<1000)return out;i+=1000}}
// Sayfa verisi: ilk çağrıda yükler, gelince ekranı yeniler. undefined = yükleniyor.
function need(k,fn){if(k in D)return D[k];if(!PEND[k])PEND[k]=fn().then(v=>{D[k]=v}).catch(e=>{D[k]=null;toast(trErr(e.message))}).finally(()=>{delete PEND[k];render()});return undefined}
const drop=(...pre)=>Object.keys(D).forEach(k=>{if(pre.some(p=>k===p||k.startsWith(p+':')))delete D[k]});
const loading=()=>'<div class="card empty">Yükleniyor…</div>';
async function loadPeople(){S.people=await all(()=>sb.from('personel_ozet').select('*').order('full_name'))}
async function loadBase(){
 const me=await rpc('whoami');S.me=me&&(me.id||me.kiosk)?me:null;S.reg=null;if(!S.me){S.reg=await rpc('my_registration').catch(()=>null)||null;return}if(S.me.kiosk||S.me.status==='ayrildi')return;
 S.kvkk=await rpc('kvkk_status').catch(()=>({ok:true}));
 sb.from('form_flows').select('*').then(r=>{S.flows=r.data||[]});rpc('news_unread').then(n=>{if(n!==D.newsN){D.newsN=n;if(S.me)render()}}).catch(()=>{});if(S.me.role==='gm'||(S.me.perms||[]).includes('proje')||(S.groups||[]).find(g=>g.id===S.me.group_id)?.tabs?.includes('plist'))loadPlan().then(()=>{if(D.planN&&S.me)render()}).catch(()=>{});FEATURES.equip&&sb.from('equipment').select('id',{count:'exact',head:true}).eq('holder_id',S.me.id).then(r=>{const n=r?.count||0;if(n!==D.myeqn){D.myeqn=n;if(n&&S.me)render()}},()=>{});
 S.groups=must(await sb.from('access_groups').select('*').order('sort'));
 const[dt,st,wd,ho,no,pr,po,de]=await Promise.all([sb.from('doc_types').select('*').order('sort'),sb.from('settings').select('*').maybeSingle(),sb.from('work_days').select('*').order('dow'),sb.from('holidays').select('*').order('day'),
  sb.from('notifications').select('*').order('created_at',{ascending:false}).limit(60),sb.from('projects').select('code,name,firm,status,special,active').order('code'),sb.from('positions').select('*').order('name'),sb.from('departments').select('*').order('sort'),loadPeople()]);
 S.docTypes=must(dt);S.settings=must(st);S.workDays=must(wd);S.hol=new Map(must(ho).map(h=>[h.day,h]));S.notifs=must(no);S.projects=byNo(must(pr));S.positions=must(po);S.deptRows=must(de);S.depts=S.deptRows.map(d=>d.name);
 // Görev verisi menüdeki onay sayısı için baştan yüklenir (her kişi sadece kendisini ilgilendireni görür)
 [D.orders,D.tasks]=await Promise.all([loadOrders(),loadTasks()]).catch(()=>[[],[]])}
const att=(emps,m)=>all(()=>{let q=sb.from('attendance').select('*').gte('day',m+'-01').lte('day',monthDays(m).at(-1)).order('day');if(emps)q=q.in('employee_id',emps);return q});
const punchesOf=(e,d,d2=d)=>all(()=>sb.from('punches').select('*').eq('employee_id',e).gte('at',dayStart(d)).lt('at',dayStart(add(d2,1))).order('at'));
// ver=true: sadece geçerli (İK onaylı) belgeler; false: kişinin kontrol bekleyen yüklemeleri de gelir
const curDocs=(e,ver=true)=>all(()=>{let q=sb.from('employee_docs').select('*').eq('replaced',false);if(e)q=q.eq('employee_id',e);if(ver)q=q.eq('verified',true);return q});
function sumAtt(L){const t={n:0,o:0,h:0,w:0,D:0,E:0,Y:0,R:0,U:0,M:0,S:0};L.forEach(a=>{t.n+=a.normal_min;t.o+=a.ot_min;t.h+=a.hol_min;if(a.code==='C'||a.code==='S')t.w++;if(a.code in t)t[a.code]++});return t}

/* ---------- genel arayüz ---------- */
function toast(t,sub){const e=document.createElement('div');e.innerHTML=`${esc(t)}${sub?`<small>${esc(sub)}</small>`:''}`;$('#toast').append(e);setTimeout(()=>e.remove(),4500)}
// Menü; '§' satırları kenar çubuğunda bölüm başlığıdır
function navs(){const L=[],sec=t=>L.push(['§',t]),me=S.me.id,mg=isMgr(),apN=jobApprovals().length;
 if(S.me.role==='gm'||(myGroup()?.tabs||[]).includes('boss'))L.push(['boss','Yönetim özeti','chart']);L.push(['home','Ana sayfa','home'],['news','Duyurular','bell',D.newsN||'']);sec('Benim işlerim');L.push(['jobs','Görevlerim','list'],['forms','Formlar','doc'],['mytime','Puantajım','clock'],['mydocs','Belgelerim','doc']);if(FEATURES.equip&&(D.myeqn||0)>0)L.push(['myeq','Zimmetim','list']);
 const bk=[];if(mg||apN||(D.tasks||[]).some(t=>t.approver_id===me))bk.push(['japp','İş onayı','check',apN]);
 if(mg)bk.push(['jpanel','Görev paneli','chart'],['tasks','Görevler','list'],['jrep','Görev raporu','chart']);
 if(bk.length){sec('Bakım ve görevler');L.push(...bk)}
 const hr=[];if(leads())hr.push(['today','Yoklama','check']);if(can('personel'))hr.push(['people','Personel','users'],['matrix','Belge matrisi','doc'],['expiry','Belge takibi','shield']);if(can('puantaj'))hr.push(['puantaj','Puantaj','cal']);if(can('personel'))hr.push(['vehicles','Şirket araçları','folder']);
 if(hr.length){sec('Personel ve puantaj');L.push(...hr)}
 if(FEATURES.equip&&can('depo')){sec('Depo ve zimmet');L.push(['equip','Ekipmanlar','folder'])}
 if(can('proje')){sec('Proje');L.push(['plist','Çalışma listesi','folder',D.planN||''])}
 if(can('ayar')||canQr()){sec('Sistem');if(can('ayar'))L.push(['settings','Ayarlar','gear']);if(canQr())L.push(['qrsites','QR noktaları','check']);if(S.me.role==='gm')L.push(['perms','Yetki ekranı','shield'])}
 // Grubunda işaretli olmayan sekmeler gizlenir; onayı bekleyen işi olan kişi İş onayını yine görür
 const F=L.filter(x=>x[0]==='§'||x[0]==='perms'||tabOk(x[0])||(x[0]==='japp'&&apN));
 return F.filter((x,i)=>x[0]!=='§'||(F[i+1]&&F[i+1][0]!=='§'))}
const navItems=()=>navs().filter(x=>x[0]!=='§');
// Kenar menüsü ağaç: bölüm başlığına basınca altındaki sekmeler açılır; açık sekmenin bölümü hep açıktır
const navOpen=()=>{try{return JSON.parse(localStorage.getItem('navOpen')||'{}')}catch{return{}}};
function navTree(nv,v){const G=[];let cur=null;nv.forEach(x=>{if(x[0]==='§'){cur={t:x[1],items:[]};G.push(cur)}else if(cur)cur.items.push(x);else G.push({items:[x]})});const st=navOpen();
 const btn=(x,sub)=>`<button class="${v===x[0]?'on':''}${sub?' sub':''}" data-go="${x[0]}">${ic(x[2])}${x[1]}${x[3]?`<span class="n">${x[3]}</span>`:''}</button>`;
 return G.map(g=>{if(!g.t)return g.items.map(x=>btn(x)).join('');if(g.items.length===1)return btn(g.items[0]);const act=g.items.some(x=>x[0]===v),op=act||(st[g.t]??g.t==='Benim işlerim'),badge=g.items.reduce((s,x)=>s+(+x[3]||0),0);
  return`<div class="grp${op?' open':''}"><button class="gh" data-act="navsec" data-k="${esc(g.t)}" aria-expanded="${op}"><span class="car" aria-hidden="true">›</span>${esc(g.t)}${!op&&badge?`<span class="n">${badge}</span>`:''}</button><div class="gi">${g.items.map(x=>btn(x,1)).join('')}</div></div>`}).join('')}
const TITLES={news:'Duyurular',vehicles:'Şirket araçları',equip:'Ekipmanlar ve zimmet',myeq:'Zimmetim',boss:'Yönetim özeti',perms:'Yetki ekranı',jobs:'Görevlerim',japp:'İş onayı',jpanel:'Görev paneli',tasks:'Görevler',qrsites:'QR noktaları',jrep:'Görev raporu',forms:'Formlar',matrix:'Belge matrisi',home:'Ana sayfa',mytime:'Puantajım',today:'Yoklama',people:'Personel',expiry:'Belge takibi',puantaj:'Puantaj',plist:'Proje çalışma listesi',mydocs:'Belgelerim',settings:'Ayarlar',notif:'Bildirimler'};
const PAGE={};
function render(){
 if(!sb){$('#root').innerHTML=`<div class="login"><div class="lbox"><img src="assets/logo.png" alt="DEFAS Mühendislik"><p>Kurulum bekleniyor: config.js dosyasına Supabase bilgileri girilmeli.</p></div></div>`;return}
 if(!S.me){$('#root').innerHTML=S.reg?regPage():loginPage();return}
 if(S.me.kiosk)return renderKiosk();
 if(S.me.status==='ayrildi'){$('#root').innerHTML=`<div class="login"><div class="lbox"><img src="assets/logo.png" alt="DEFAS"><p>Hesabınız kapatılmıştır.</p><button class="btn" style="width:100%" data-act="logout">Çıkış yap</button></div></div>`;return}
 if(S.me.must_change_pw){$('#root').innerHTML=pwPage();return}
 if(S.kvkk&&!S.kvkk.ok){$('#root').innerHTML=kvkkPage();return}
  if(S.me.status==='aday'||S.me.portal_wait){$('#root').innerHTML=gatePage();hydrate();return}
 if(S.kioskTimer){clearInterval(S.kioskTimer);S.kioskTimer=null}
 const nv=navs(),n=nv.filter(x=>x[0]!=='§');if(!S.view||(!n.some(x=>x[0]===S.view)&&S.view!=='notif'))S.view=n[0][0];
 const v=S.view,un=S.notifs.filter(x=>!x.read).length,mob=n.slice(0,4),me=S.me;
 const keep=$('.page')?scrollY:0,same=render.last===v;render.last=v;
 $('#root').innerHTML=`<div class="app"><aside class="side"><div class="logo"><img src="assets/logo.png" alt="DEFAS Mühendislik"></div><nav class="nav">${navTree(nv,v)}</nav><div class="me"><button class="who" data-act="logout"><span class="av">${init(me.full_name)}</span><span><b>${esc(me.full_name)}</b><small>${esc(me.dept)} · Çıkış yap</small></span></button></div></aside>
 <div class="main"><header class="top"><img class="mlogo" src="assets/logo.png" alt="DEFAS"><h1>${TITLES[v]||''}</h1><button class="bell" data-go="notif" aria-label="Bildirimler">${ic('bell',22)}${un?`<i>${un}</i>`:''}</button></header><main class="page${v==='puantaj'||v==='matrix'||v==='perms'?' wide':''}">${PAGE[v]()}</main></div></div>
 <nav class="bnav">${mob.map(x=>`<button class="${v===x[0]?'on':''}" data-go="${x[0]}">${ic(x[2],22)}${x[1].split(' ')[0]}</button>`).join('')}<button data-act="more">${ic('more',22)}Daha</button></nav>`;
 const sr=$('#simres');if(sr)sr.innerHTML=simText();hydrate();
 if(same)scrollTo(0,keep)}
