const reqFor=(t,p)=>{const g=(p?.emp_group||'').toLocaleLowerCase('tr');return g.includes('mavi')?(t.req_mavi??t.required):g.includes('beyaz')?(t.req_beyaz??t.required):t.required};
const reqTypes=p=>S.docTypes.filter(t=>t.active&&reqFor(t,p));
function empState(p,docs){if(p.status==='ayrildi')return pill(STAT.ayrildi);if(p.status==='aday'){const have=new Set(docs.filter(d=>d.employee_id===p.id).map(d=>d.doc_type_id)),R=reqTypes(p);return pill(['warn',`Aday · belge ${R.filter(t=>have.has(t.id)).length}/${R.length}`])}return p.block?pill(['bad','Çalışamaz']):pill(STAT.aktif)}
PAGE.people=()=>{const E=need('emps',()=>all(()=>sb.from('employees').select('*').order('full_name'))),Dc=need('alldocs',()=>curDocs());if(E===undefined||Dc===undefined)return loading();
 const f=ui.pf||'aktif',q=norm(ui.pq),dep=ui.pdep||'';let L=S.people.filter(p=>f==='hepsi'||(f==='engel'?p.status==='aktif'&&p.block:p.status===f));if(dep)L=L.filter(p=>p.dept===dep);if(ui.pgrp)L=L.filter(p=>p.emp_group===ui.pgrp);if(q)L=L.filter(p=>norm(p.full_name+' '+(p.sicil||'')+' '+(p.position||'')).includes(q));
 const cnt=k=>S.people.filter(p=>k==='engel'?p.status==='aktif'&&p.block:p.status===k).length;
 const RG=need('regs',()=>rpc('pending_registrations'))||[];
 return`${RG.length?`<div class="card" style="border-color:var(--warn)"><div class="h"><h2>Üyelik başvuruları</h2><span class="pill warn">${RG.length} onay bekliyor</span></div>${RG.map(r=>`<div class="row"><span class="t"><b>${esc(r.first_name+' '+r.last_name)}</b><small>${esc(r.email)} · ${esc(dmy(r.created_at))}${r.suggested_emp?' · mevcut kayıt: '+esc(nm(r.suggested_emp)):' · yeni personel'}${r.email_confirmed===false?' · e-postasını henüz doğrulamadı':''}</small></span><button class="btn sm p" data-act="regdlg" data-id="${r.user_id}">İncele</button></div>`).join('')}</div>`:''}<div class="tools"><div class="seg">${[['aktif','Aktif'],['aday','Aday'],['engel','Çalışamaz'],['ayrildi','Ayrılan'],['hepsi','Tümü']].map(([k,t])=>`<button class="${f===k?'on':''}" data-act="pf" data-k="${k}">${t}${k!=='hepsi'?` <small>${cnt(k)}</small>`:''}</button>`).join('')}</div><span class="grow"></span><button class="btn p" data-act="newemp">${ic('plus',18)}Yeni personel</button></div>
 <div class="tools"><input class="inp" style="flex:1;min-width:180px" placeholder="Ad, sicil veya unvan ara" value="${esc(ui.pq||'')}" data-in="pq"><select class="inp" style="width:auto" data-in="pdep">${opts(S.depts.map(d=>[d,d]),dep,'Tüm birimler')}</select><select class="inp" style="width:auto" data-in="pgrp">${opts(groups().map(g=>[g,g]),ui.pgrp,'Tüm gruplar')}</select></div>
 <div class="tools noprint"><button class="btn" data-act="imp">${ic('up',18)}Excel'den toplu aktar</button>${canHR()?`<button class="btn" data-act="yakadlg">${ic('doc',18)}Yaka bazlı zorunlu belgeler</button><button class="btn" data-act="kadrodlg">${ic('list',18)}Zorunlu kadro</button><button class="btn" data-act="kvkkrep">${ic('shield',18)}KVKK onayları</button>`:''}${can('personel')||S.me.role==='gm'||S.me.role==='mgr'?`<button class="btn" data-act="vekil">${ic('users',18)}Vekil listesi</button>`:''}<span class="grow"></span><button class="btn" data-act="xplist">${ic('down',18)}Güncel Personel Listesi</button><button class="btn" data-act="xizin">${ic('down',18)}Yıllık İzin Tablosu</button><button class="btn" data-act="xgorev">${ic('down',18)}Görev listesi şablonu</button><button class="btn" data-act="xpeople">${ic('down',18)}Sistem dökümü</button><button class="btn" data-act="xsizes">${ic('down',18)}Beden listesi</button><button class="btn" data-act="allzip">${ic('down',18)}Tüm belgeler (ZIP yedek)</button></div>
 ${noPosMsg(E)}${f==='aday'?'<div class="msg info">Aday personel, zorunlu belgelerin hepsi yüklenince kendiliğinden aktif olur ve çalışma listesine yazılabilir.</div>':''}${f==='engel'?'<div class="msg bad">Bu kişilerin belgesi eksik veya süresi dolmuş. Belge yenilenene kadar proje çalışma listesine yazılamazlar.</div>':''}
 <div class="card">${L.map(p=>`<button class="row" data-act="emp" data-id="${p.id}"><span class="av">${init(p.full_name)}</span><span class="t"><b>${esc(p.full_name)}</b><small>${p.sicil?'Sicil '+esc(p.sicil)+' · ':''}${esc(p.dept)}${p.position?' · '+esc(p.position):''}${p.status==='aktif'&&p.block?' · <span style="color:var(--bad)">'+esc(p.block)+'</span>':''}</small></span>${p.has_account?'':'<span class="pill gray hm">Hesap yok</span>'}${empState(p,Dc||[])}</button>`).join('')||'<div class="empty">Kayıt yok</div>'}</div>`};

