 if(isNew)return dlg('Yeni personel','Kayıt aday olarak açılır, zorunlu belgeler tamamlanınca aktif olur',info,'',true);
 const by=new Map(docs.map(d=>[d.doc_type_id,d]));
 const docsH=`<div class="sect"><h3>${ic('doc',18)}Belgeler<span class="grow"></span>${docs.some(d=>d.file_path)?`<button class="btn sm" data-act="emppdf" data-id="${id}">${ic('down',16)}Tümü tek PDF</button>`:''}</h3>${(D.pendocs||[]).filter(d=>d.employee_id===id).map(d=>`<div class="msg warn">Personelin yüklediği <b>${esc(S.docTypes.find(t=>t.id===d.doc_type_id)?.name)}</b> kontrol bekliyor. <button class="btn sm" data-act="viewdoc" data-p="${esc(d.file_path||'')}">Aç</button> <button class="btn sm ok" data-act="verdoc" data-ok="1" data-id="${d.id}">Onayla</button> <button class="btn sm bad" data-act="verdoc" data-ok="" data-id="${d.id}">Reddet</button></div>`).join('')}${p.status==='aday'?`<div class="msg warn">Personel aday. Eksik zorunlu belgeler: <b>${esc(reqTypes(p).filter(t=>!by.has(t.id)).map(t=>t.name).join(', ')||'yok')}</b>. Hepsi yüklenince kendiliğinden aktif olur.</div>`:p.block&&!gone?`<div class="msg bad">Çalışamaz: ${esc(p.block)}</div>`:''}
  ${(()=>{const T=S.docTypes.filter(t=>(t.active&&reqFor(t,p))||by.has(t.id)),rest=S.docTypes.filter(t=>t.active&&!T.includes(t));return cats(T).map(c=>`<div style="font-size:12.5px;font-weight:700;color:var(--ink3);margin:10px 0 2px;text-transform:uppercase">${esc(c)}</div>`+T.filter(t=>t.category===c).map(t=>{const d=by.get(t.id);return`<div class="row" style="padding-inline:0"><span class="t"><b>${esc(t.name)}${t.blocks_work?' <span class="pill info" title="Süresi dolarsa çalışma listesine yazılamaz">Engelleyici</span>':''}</b><small>${d?docInfo(d):reqFor(t,p)?'Zorunlu belge':'İsteğe bağlı'}</small></span>${docPill(t,d,p)}${d?.file_path?`<button class="btn sm" data-act="viewdoc" data-p="${esc(d.file_path)}" aria-label="Aç">${ic('eye',16)}</button><button class="btn sm" data-act="dldoc" data-p="${esc(d.file_path)}" aria-label="PDF indir">${ic('down',16)}</button>`:''}${gone?'':`<button class="btn sm" data-act="updoc" data-id="${id}" data-t="${t.id}">${ic('up',16)}${d?'Yenile':'Yükle'}</button>`}</div>`}).join('')).join('')+(gone||!rest.length?'':`<div class="tools" style="margin-top:10px"><select class="inp" name="extra_t" style="flex:1">${opts(rest.map(t=>[t.id,t.category+' · '+t.name]),'','Başka belge / sertifika ekle…')}</select><button class="btn" data-act="updocx" data-id="${id}">${ic('plus',16)}Ekle</button></div>`)})()}</div>`;
 const acc=gone?'':`<div class="sect"><h3>Giriş hesabı</h3>${p.has_account?`<div class="tools"><span class="grow" style="color:var(--ink2)">Hesabı var${E.sicil?' · giriş: sicil '+esc(E.sicil):''}</span><button class="btn" data-act="resetpw" data-id="${id}">Şifreyi sıfırla</button></div>`:`<div class="two"><label class="f">Giriş adı (sicil no veya e-posta)<input class="inp" name="login" value="${esc(E.sicil||E.email||'')}"></label><label class="f">Geçici şifre<input class="inp" name="pw" value="${genPw()}"></label></div><button class="btn" data-act="mkacc" data-id="${id}">Hesap aç</button>`}</div>`;
 const lv=gone?'':`<div class="sect"><h3>İzin ve vekil (görev devri)</h3><div class="two"><label class="tog"><span>İzinli veya raporlu</span><input type="checkbox" name="lv_on" ${E.on_leave?'checked':''}></label><label class="f">Vekil (gelmediğinde işleri ona geçer)<select class="inp" name="lv_backup">${opts(S.people.filter(x=>x.status==='aktif'&&x.id!==id&&x.dept===(E.dept||'')).map(x=>[x.id,pnm(x)]),E.backup_id,'Yok')}</select></label></div><button class="btn" data-act="handover" data-id="${id}">Kaydet ve açık işleri vekile devret</button><small style="display:block;color:var(--ink3);margin-top:6px">İzinliyken yeni açılan işler vekile gider.</small>${can('personel')||can('puantaj')?`<div class="tools" style="margin-top:10px"><span class="grow" style="color:var(--ink2)">QR telefonu: ${E.device_id?'kayıtlı ('+esc(dmy(E.device_at))+')':'henüz kayıtlı değil (ilk okuttuğu telefona bağlanır)'}</span>${E.device_id?`<button class="btn sm" data-act="resetdev" data-id="${id}">Telefon kaydını sıfırla</button>`:''}</div>`:''}</div>`;
 const perm=me.role==='gm'&&!gone?`<div class="sect"><h3>Yetki</h3><div class="two"><div><label class="f">Yetki grubu<select class="inp" name="grp">${opts((S.groups||[]).map(g=>[g.id,g.name]),E.group_id,'Grup yok')}</select></label><label class="f">Rol<select class="inp" name="role">${opts(Object.entries(ROLES),E.role)}</select></label><small style="color:var(--ink3)">Grubun göreceği sekmeler Yetki ekranından belirlenir. Sağdakiler gruba ek yetkidir.</small></div><div>${Object.entries(PERMS).map(([k,t])=>`<label class="tog"><span>${t}</span><input type="checkbox" name="perm_${k}" ${(E.perms||[]).includes(k)?'checked':''}></label>`).join('')}</div></div><button class="btn" data-act="saveacc" data-id="${id}">Yetkiyi kaydet</button></div>`:'';
 const ex=gone?`<div class="sect"><h3>İşten çıkış</h3><dl class="kv"><dt>Son çalışma günü</dt><dd>${esc(dmy(E.exit_date))}</dd><dt>Neden</dt><dd>${esc(E.exit_reason||'—')}</dd></dl>${me.role==='gm'?`<button class="btn" style="margin-top:10px" data-act="undoexit" data-id="${id}">Çıkışı geri al</button>`:''}</div>`
  :`<div class="sect"><h3>İşten çıkış</h3>${E.exit_date?`<div class="msg warn">Son çalışma günü ${esc(dmy(E.exit_date))} olarak girildi.</div>`:''}<div class="two"><label class="f">Son çalışma günü<input class="inp" type="date" name="exit_date" value="${esc(E.exit_date||'')}"></label><label class="f">Neden<input class="inp" name="exit_reason" placeholder="Örn. istifa"></label></div><button class="btn bad" data-act="exitemp" data-id="${id}">İşten çıkışı kaydet</button><small style="display:block;color:var(--ink3);margin-top:6px">Son günden sonraki çalışma listelerinden çıkarılır, hesabı kapanır, bir daha listeye yazılamaz.</small></div>`;
