/* Eski Excel'den aktarım (Çalışma Listesi.xlsm) */
async function parseWL(files){const X=await loadXl(),I={projects:[],entries:[],people:[],notes:[],skip:0},UP=c=>String(c??'').toLocaleUpperCase('tr').replace(/\s+/g,' ').trim(),spc={'YILLIK İZİN':'YILLIK İZİN','ÜCRETSİZ İZİN':'ÜCRETSİZ İZİN','RAPORLU':'RAPORLU'};
 for(const f of files){const wb=X.read(await f.arrayBuffer());for(const sn of wb.SheetNames){const R=X.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:'',raw:true}).filter(r=>!r.some(c=>/\(ÖRNEK\)/i.test(String(c))));if(!R.length)continue;const H=(R[0]||[]).map(UP),col=re=>H.findIndex(h=>re.test(h));
  if(col(/^PROJE KODU$/)>=0&&col(/HEDEF/)>=0){const c={o:col(/TEKL[İI]F NO/),k:col(/^PROJE KODU$/),s:col(/FATURA|DURUM/),si:col(/S[İI]PAR[İI]Ş/),n:col(/PROJE ADI/),fi:col(/F[İI]RMA/),ct:col(/SORUMLUSU/),t:col(/HEDEF/),e:col(/MÜHEND[İI]S/),no:col(/NOT/)};
   R.slice(1).forEach(r=>{const k=String(r[c.k]||'').trim();if(!k)return;I.projects.push({code:k,name:String(r[c.n]||'').trim(),firm:String(r[c.fi]||'').trim(),offer_no:c.o>=0?String(r[c.o]||'').trim():'',order_no:c.si>=0?String(r[c.si]||'').trim():'',contact:c.ct>=0?String(r[c.ct]||'').trim():'',engineer:c.e>=0?String(r[c.e]||'').trim():'',target:c.t>=0&&r[c.t]!==''&&!isNaN(+r[c.t])?+r[c.t]:'',status:c.s>=0?String(r[c.s]||'').trim():'',notes:c.no>=0?String(r[c.no]||'').trim():''})});I.notes.push(`${f.name} › ${sn}: ${I.projects.length} proje`);continue}
  if(col(/^PERSONEL$/)>=0&&col(/MESA[İI] TÜRÜ/)>=0){const c={p:col(/^PERSONEL$/),k:col(/PROJE KODU/),t:col(/MESA[İI] TÜRÜ/),h:col(/SÜRE/),d:col(/TAR[İI]H/)};let n=0;
   R.slice(1).forEach(r=>{const name=String(r[c.p]||'').trim(),kind=String(r[c.t]||'').trim(),day=xlDate(r[c.d]);let code=String(r[c.k]||'').trim();if(!name||!day)return;if(/AYRILDI|YEN[İI] G[İI]R[İI]Ş/i.test(UP(kind))){I.skip++;return}
    code=spc[UP(code)]||UP(code);const k2=/FAZLA/i.test(kind)?'Fazla Mesai':/[İI]Z[İI]N|ÖZEL/i.test(UP(kind))?'İzin/Özel Durum':'Mesai';I.entries.push({day,name,code,kind:k2,hours:+r[c.h]||0});n++});I.notes.push(`${f.name} › ${sn}: ${n} çalışma kaydı`);continue}
  if(col(/POZ[İI]SYON/)>=0&&col(/PERSONEL [İI]S[İI]M/)>=0){const c={y:col(/POZ[İI]SYON/),e:col(/^EK[İI]P$/),n:col(/PERSONEL [İI]S[İI]M/)};R.slice(1).forEach(r=>{const n=String(r[c.n]||'').trim();if(n)I.people.push({name:n,crew:r[c.e]===''?null:+r[c.e],yaka:String(r[c.y]||'').trim()})});I.notes.push(`${f.name} › ${sn}: ${I.people.length} listedeki personel`)}}}
 I.match=I.people.map(x=>({...x,p:S.people.find(p=>norm(p.full_name)===norm(x.name)&&p.status!=='ayrildi')}));ui.wimp=I;wlImpDlg()}
function wlImpDlg(){const I=ui.wimp,miss=I.match.filter(x=>!x.p);ui.modal=[wlImpDlg];
 dlg("Excel'den aktarım",'Çalışma Listesi.xlsm',`${I.notes.length?`<div class="msg info">${I.notes.map(esc).join('<br>')}</div>`:'<div class="msg warn">Tanınan sayfa yok (Proje_Kodu, Calisma_Listesi, Veri_Girisi).</div>'}
 <div class="grid g2" style="margin-bottom:12px"><div class="tile"><small>Proje kodu</small><b>${I.projects.length}</b></div><div class="tile"><small>Çalışma kaydı</small><b>${I.entries.length}</b></div><div class="tile"><small>Liste personeli (eşleşen)</small><b>${I.match.length-miss.length} / ${I.match.length}</b></div><div class="tile"><small>Atlanan (Yeni Giriş / Ayrıldı)</small><b>${I.skip}</b></div></div>
 ${miss.length?`<div class="msg warn"><b>Sistemde bulunamayan ${miss.length} kişi</b> listeye işaretlenemedi (geçmiş kayıtları isimleriyle yine aktarılır): ${esc(miss.map(x=>x.name).join(', '))}</div>`:''}
 <div class="msg info">Geçmiş kayıtlar kural kontrolü yapılmadan, isimleriyle aktarılır; aynı satır ikinci kez yazılmaz. "Yeni Giriş" ve "Ayrıldı" satırları yeni sistemde İK'nın işe giriş ve çıkış işlemleriyle yürüdüğü için alınmaz.</div>`,`<button class="btn" data-act="close">Vazgeç</button><button class="btn p" data-act="wldoimp">Aktar</button>`,true)}
