const loadOrders=()=>all(()=>sb.from('work_orders').select('*,work_order_items(*)').or(`work_date.gte.${add(TODAY,-14)},status.in.(bekliyor,geri,onayda,yapilamadi)`).order('work_date'));
const loadTasks=()=>all(()=>sb.from('task_templates').select('*').eq('active',true).order('group_title'));
const isMgr=()=>S.me.role==='gm'||S.me.role==='mgr'||can('gorev');
const isMgrOf=d=>S.me.role==='gm'||((S.me.role==='mgr'||can('gorev'))&&S.me.dept===d);
const per=p=>({0:'Tek seferlik',1:'Günlük',7:'Haftalık',15:'15 günlük',30:'Aylık',90:'3 aylık',180:'6 aylık',365:'Yıllık',730:'2 yıllık'}[p]||`${p} günde bir`);
const lateO=o=>['bekliyor','geri'].includes(o.status)&&o.work_date<TODAY;
const ostt=o=>lateO(o)?['bad','Gecikti']:({bekliyor:['gray','Bekliyor'],onayda:['info','Onay bekliyor'],geri:['warn','Geri gönderildi'],onaylandi:['ok','Onaylandı'],tamamlandi:['ok','Tamamlandı'],yapilamadi:['bad','Yapılamadı']}[o.status]);
const canApO=o=>o.approver_id===S.me.id||isMgrOf(o.dept);
const jobApprovals=()=>(D.orders||[]).filter(o=>canApO(o)&&(o.status==='onayda'||(o.status==='yapilamadi'&&!o.ack)));
const oscope=o=>S.me.role==='gm'||o.dept===S.me.dept;
