async function chunked(fn,rows,size){const out={added:0,updated:0,same:0,skipped:[]};for(let i=0;i<rows.length;i+=size){const r=await rpc(fn,{p_rows:rows.slice(i,i+size)});out.added+=r.added||0;out.updated+=r.updated||0;out.same+=r.same||0;out.skipped.push(...(r.skipped||[]))}return out}

