PAGE.qrsites=()=>{const L=need('qrs',loadSites);if(L===undefined)return loading();const fab=(L||[]).filter(s=>s.kind==='fabrika'),san=(L||[]).filter(s=>s.kind==='santiye');
 const card=s=>`<div class="row"><span class="t"><b>${esc(s.name)}</b><small>${s.kind==='fabrika'?'Süresiz':esc(dmy(s.valid_from))+' – '+esc(s.valid_to?dmy(s.valid_to):'süresiz')} · ${s.geo_check===false?'konum sorulmaz':s.radius_m+' m çevre'}${s.project_code?' · '+esc(s.project_code):''}${s.start_time?' · '+DOW.filter((_,i)=>s.work_days.includes(i+1)).join(', ')+' '+hh(s.start_time)+'–'+hh(s.end_time):' · genel çalışma saatleri'}</small></span>${pill(siteState(s))}<button class="btn sm" data-act="qrposter" data-id="${s.id}">${ic('down',16)}Afiş</button><button class="btn sm" data-act="qrsite" data-id="${s.id}">Düzenle</button></div>`;
 return`<div class="tools"><span class="grow" style="color:var(--ink2)">Basılı QR kapıya asılır. Personel kendi telefonuyla okutur; konumu noktanın çevresinde değilse veya başkasının telefonuysa kayıt alınmaz.</span><button class="btn p" data-act="qrsite" data-id="">${ic('plus',18)}Yeni QR noktası</button></div>
 <div class="card"><div class="h"><h2>Fabrika (kalıcı)</h2></div>${fab.map(card).join('')||`<div class="empty">Fabrika kapısı için QR noktası yok. ${S.me.role==='gm'||can('ayar')?'“Yeni QR noktası” ile fabrika türünde açın.':'Genel yönetici açabilir.'}</div>`}</div>
 <div class="card"><div class="h"><h2>Şantiyeler (geçici)</h2></div>${san.map(card).join('')||'<div class="empty">Şantiye QR noktası yok</div>'}</div>
 <div class="sample">Şantiye QR'ı ile giriş yapan personelin puantajı o şantiyenin çalışma günleri ve saatlerine göre hesaplanır (yuvarlama kuralları aynı). Bitiş tarihinden sonra kod kendiliğinden geçersiz olur. Afiş dışarı sızarsa “Düzenle › Kodu yenile” ile eski çıktı iptal edilir.</div>`};
function parseLoc(v){const s=String(v||'').trim();let m=s.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/)||s.match(/[?&](?:q|query|ll)=(-?\d+\.\d+),\s*(-?\d+\.\d+)/)||s.match(/^(-?\d{1,2}\.\d+)\s*[,; ]\s*(-?\d{1,3}\.\d+)$/);return m?{lat:+m[1],lng:+m[2]}:null}
function siteDlg(id){const L=D.qrs||[],s=id?L.find(x=>String(x.id)===String(id)):null,full=S.me.role==='gm'||can('ayar');ui.modal=[siteDlg,id];const f=ui.sf=ui.sf&&ui.sf.id===id?ui.sf:{id,loc:s?`${s.lat}, ${s.lng}`:'',kind:s?.kind||(full&&!L.some(x=>x.kind==='fabrika')?'fabrika':'santiye'),days:s?[...s.work_days]:[1,2,3,4,5],own:!!s?.start_time};
 const v=(k,d='')=>esc(s?.[k]??d),act=(S.projects||[]).filter(p=>p.active&&!p.special);
 dlg(id?s.name:'Yeni QR noktası','Kapıya asılacak basılı QR kodu',`<div class="two"><label class="f">Adı<input class="inp" name="qs_name" value="${v('name')}" placeholder="${f.kind==='fabrika'?'Fabrika personel girişi':'Ör. İzmit Rafineri Şantiyesi'}"></label><label class="f">Tür<select class="inp" name="qs_kind" data-qsre="1" ${full?'':'disabled'}>${opts([['fabrika','Fabrika (kalıcı, süresiz)'],['santiye','Şantiye (geçici)']],f.kind)}</select></label></div>
 <label class="f">Konum (enlem, boylam ya da Google Haritalar bağlantısı)<input class="inp" name="qs_loc" value="${esc(f.loc)}" placeholder="39.7767, 30.5206"></label>
 <div class="tools" style="margin:-4px 0 10px"><button class="btn sm" data-act="qshere">${ic('check',16)}Bulunduğum konumu al</button>${f.loc&&parseLoc(f.loc)?`<a class="btn sm" target="_blank" rel="noopener" href="https://www.google.com/maps?q=${encodeURIComponent(f.loc.replace(/\s/g,''))}">Haritada gör</a>`:''}<small style="color:var(--ink3)">Kapının önünde telefonla “Bulunduğum konumu al” demek en doğrusu.</small></div>
 <div class="two"><label class="f">Kabul çevresi (metre)<input class="inp" type="number" min="30" max="3000" name="qs_r" value="${v('radius_m',f.kind==='fabrika'?150:300)}"></label>${f.kind==='santiye'?`<label class="f">Proje kodu (isteğe bağlı)<select class="inp" name="qs_proj">${opts(act.map(p=>[p.code,p.code+' · '+p.name]),s?.project_code||'','Yok')}</select></label><label class="f">Başlangıç<input class="inp" type="date" name="qs_from" value="${v('valid_from')}"></label><label class="f">Bitiş (proje sonu)<input class="inp" type="date" name="qs_to" value="${v('valid_to')}"></label>`:''}</div>
 <label class="tog"><span>Konum kontrolü <small style="display:block;color:var(--ink3);font-weight:400">Açıksa okutan telefon bu noktanın yakınında olmalı (konum izni ister). Kapalıysa konum sorulmaz; kişi kendi telefonuyla okutur, okutmalar "konumsuz" diye işaretlenir.</small></span><input type="checkbox" name="qs_geo" ${s&&s.geo_check===false?'':'checked'}></label>
 ${f.kind==='santiye'?`<label class="tog"><span>Şantiyenin kendi çalışma saatleri var</span><input type="checkbox" name="qs_own" data-qsre="1" ${f.own?'checked':''}></label>${f.own?`<label class="f">Çalışma günleri</label><div class="chips" style="margin-bottom:10px">${DOW.map((d,i)=>`<button class="chip ${f.days.includes(i+1)?'on':''}" data-act="qsday" data-d="${i+1}">${d}</button>`).join('')}</div><div class="two"><label class="f">Başlangıç saati<input class="inp" type="time" name="qs_st" value="${hh(s?.start_time)||'08:00'}"></label><label class="f">Bitiş saati<input class="inp" type="time" name="qs_et" value="${hh(s?.end_time)||'18:00'}"></label><label class="f">Öğle arası başlangıç<input class="inp" type="time" name="qs_bs" value="${hh(s?.break_start)||hh(S.settings?.break_start)}"></label><label class="f">Öğle arası bitiş<input class="inp" type="time" name="qs_be" value="${hh(s?.break_end)||hh(S.settings?.break_end)}"></label></div>`:'<div class="msg info">İşaretlenmezse firmanın genel çalışma saatleri geçerli.</div>'}`:''}
 ${id?`<label class="tog"><span>Aktif</span><input type="checkbox" name="qs_act" ${s.active?'checked':''}></label>`:''}`,
 `${id?`<button class="btn" data-act="qsrenew" data-id="${id}">Kodu yenile</button>`:''}<button class="btn" data-act="close">Vazgeç</button><button class="btn p" data-act="qssave" data-id="${id||''}">Kaydet</button>`,true)}
function qsRead(){const f=ui.sf;['loc'].forEach(k=>{const e=$(`#ov [name="qs_${k}"]`);if(e)f.loc=e.value});const k=$('#ov [name="qs_kind"]');if(k)f.kind=k.value;const o=$('#ov [name="qs_own"]');if(o)f.own=o.checked}
async function qrPoster(s){const q=(await loadQr())(0,'H');q.addData(qrUrl(s));q.make();const svg=q.createSvgTag({cellSize:10,margin:2,scalable:true}),w=window.open('','_blank');if(!w)throw new Error('Açılır pencere engellendi, tarayıcıda izin verin');
 w.document.write(`<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>${esc(s.name)} QR</title><style>@page{size:A4;margin:14mm}body{font-family:Segoe UI,Arial,sans-serif;text-align:center;color:#111;margin:0}img.lg{width:230px;margin-top:6mm}h1{font-size:30px;margin:8mm 0 2mm}h2{font-size:20px;font-weight:600;margin:0 0 6mm;color:#333}.q{width:125mm;height:125mm;margin:0 auto}.q svg{width:100%;height:100%}ol{text-align:left;font-size:17px;line-height:1.6;max-width:150mm;margin:8mm auto 0}p.s{font-size:13px;color:#555;margin-top:6mm}</style></head><body><img class="lg" src="${qrBase()}assets/logo.png" alt="DEFAS"><h1>PERSONEL GİRİŞ – ÇIKIŞ</h1><h2>${esc(s.name)}</h2><div class="q">${svg}</div><ol><li>Telefonunuzun kamerasıyla QR kodu okutun.</li><li>Açılan sayfada kendi hesabınızla giriş yapın (bir kez).</li><li>Konum iznine <b>İzin ver</b> deyin. Giriş ve çıkışta tekrar okutun.</li></ol><p class="s">${s.kind==='fabrika'?'Süresiz':'Geçerlilik: '+esc(dmy(s.valid_from))+' – '+esc(s.valid_to?dmy(s.valid_to):'süresiz')}${s.start_time?' · Çalışma saatleri '+hh(s.start_time)+'–'+hh(s.end_time):''} · Okutma sadece bu noktanın ${s.radius_m} m çevresinde ve kendi telefonunuzla kabul edilir.</p><script>window.onload=()=>setTimeout(()=>print(),300)<\/script></body></html>`);w.document.close();winBar(w)}
// Uygulama içinden QR okutma: kamera açılır, DEFAS QR kodu (kapı / şantiye / kapı ekranı) okununca giriş-çıkış kaydedilir
let jsqrLib;const loadJsQR=()=>jsqrLib||(jsqrLib=new Promise((ok,no)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js';s.onload=()=>ok(window.jsQR);s.onerror=()=>{jsqrLib=null;no(new Error('QR okuyucu yüklenemedi, internet bağlantınızı kontrol edin'))};document.head.append(s)}));
const camStop=()=>{try{ui.cam&&ui.cam.getTracks().forEach(t=>t.stop())}catch{}ui.cam=null;clearTimeout(ui.camT)};
const qrCard=()=>S.me&&!S.me.kiosk&&S.me.status==='aktif'?`<div class="card pad" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap">${ic('qr',30)}<span style="flex:1;min-width:180px"><b>Giriş / çıkış</b><br><small style="color:var(--ink3)">Kapıdaki veya şantiyedeki QR kodu buradan okutun</small></span><button class="btn p" data-act="qrscan">${ic('cam',18)}QR okut</button></div>`:'';
{const H=PAGE.home,M=PAGE.mytime,B=PAGE.boss;PAGE.home=()=>qrCard()+H();PAGE.mytime=()=>qrCard()+M();PAGE.boss=()=>qrCard()+B()}
async function qrScan(){
 if(!navigator.mediaDevices?.getUserMedia)throw new Error('Bu tarayıcı kamerayı desteklemiyor. Telefonun kendi kamerasıyla okutun');
 dlg('QR okut','Kodu çerçevenin içine getirin',`<div style="position:relative;background:#000;border-radius:10px;overflow:hidden;aspect-ratio:1/1;max-width:420px;margin:0 auto"><video id="qrv" playsinline muted autoplay style="width:100%;height:100%;object-fit:cover"></video><div style="position:absolute;inset:14%;border:3px solid rgba(255,255,255,.85);border-radius:12px;box-shadow:0 0 0 999px rgba(0,0,0,.25)"></div></div><p id="qrm" style="text-align:center;color:var(--ink3);margin:10px 0 0">Kamera açılıyor… İzin sorulursa “İzin ver” deyin.</p>`,`<button class="btn" data-act="close">Kapat</button>`);
 let jsQR;try{[jsQR,ui.cam]=await Promise.all([loadJsQR(),navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false})])}catch(e){camStop();close();throw new Error(e&&e.name==='NotAllowedError'?'Kamera izni verilmedi. Ayarlar > Safari (veya uygulama) > Kamera iznini açın':e.message||'Kamera açılamadı')}
 const v=$('#qrv');if(!v){camStop();return}v.srcObject=ui.cam;try{await v.play()}catch{}
 const cv=document.createElement('canvas'),cx=cv.getContext('2d',{willReadFrequently:true});const m=$('#qrm');if(m)m.textContent='QR kodu çerçeveye getirin';
 const tick=()=>{if(!ui.cam||!$('#qrv'))return camStop();
  if(v.readyState>=2&&v.videoWidth){const w=Math.min(720,v.videoWidth),h=Math.round(v.videoHeight*w/v.videoWidth);cv.width=w;cv.height=h;cx.drawImage(v,0,0,w,h);const r=jsQR(cx.getImageData(0,0,w,h).data,w,h,{inversionAttempts:'dontInvert'});
   if(r&&r.data){let t=null;try{t=new URL(r.data,location.href).searchParams.get('qr')}catch{}
    if(t){camStop();close();sessionStorage.setItem('qr',t);doQr();return}
    if(m)m.innerHTML='<b style="color:var(--bad)">Bu bir DEFAS giriş-çıkış kodu değil.</b> Kapıdaki / şantiyedeki kodu okutun.'}}
  ui.camT=setTimeout(tick,180)};tick()}async function doQr(){if(S.kvkk&&!S.kvkk.ok)return;const t=sessionStorage.getItem('qr');if(!t)return;sessionStorage.removeItem('qr');
 // Okundu onayı istenen duyuru varsa: önce ekrana gelir, "Okudum, anladım" işaretlenince giriş kaydedilir
 if(!ui.ackDone&&S.me){let P=[];try{P=await rpc('news_ack_pending')||[]}catch{}if(P.length){ui.ackT=t;return ackDlg(P)}}ui.ackDone=false;
 try{let a={p_token:t},r;if(t.startsWith('P.'))a.p_device=devId();
  // Önce konumsuz denenir: noktada konum kontrolü kapalıysa konum hiç sorulmaz. Açıksa sunucu KONUM_GEREKLI der, o zaman konum alınır.
  try{r=await rpc('qr_punch',a)}catch(e){if(!String(e.message).includes('KONUM_GEREKLI'))throw e;
   dlg('QR okutma','',`<div class="okbox"><div class="ring">${ic('clock',44)}</div><b>Konumunuz alınıyor…</b><span>Telefon konum izni sorarsa <b>İzin ver</b> deyin.</span></div>`,'');
   const c=await getPos();r=await rpc('qr_punch',{...a,p_lat:c.latitude,p_lng:c.longitude,p_acc:c.accuracy})}drop('mypunch','my','board');render();
  dlg('QR okutma',r.site||'',`<div class="okbox"><div class="ring ${r.warn?'warn':'ok'}">${ic('check',44)}</div><b>${r.kind==='giris'?'Giriş':'Çıkış'} kaydedildi</b><span style="font-size:22px;font-weight:700">${tm(r.at)}</span><span>${r.kind==='giris'?'İyi çalışmalar':'İyi akşamlar'}, ${esc(String(r.name).split(' ')[0])}</span>${r.projects?`<div class="msg info" style="margin-top:6px"><b>Bugünkü çalışma listen:</b> ${esc(r.projects)}</div>`:''}${r.dup?'<div class="msg info">Bu okutma az önce zaten kaydedilmişti.</div>':''}${r.warn?`<div class="msg warn">Belge uyarısı: ${esc(r.warn)}. İK ile görüş.</div>`:''}</div>`,`<button class="btn p" data-act="close">Tamam</button>`)}
 catch(e){if(/Mesai yemeğini onaylamadan/.test(e.message||'')){delete D.meal;close();go('home');return toast('Önce mesai yemeğini onaylayın','Ana sayfadaki "Mesai yemeği" kartından onaylayıp QR\'ı tekrar okutun')}const m=trErr(e.message),help=e.html||(/hassas değil|uzakta/.test(m)?geoHelp(2):'');ui.lastQr=t;
  dlg('QR okutma','',`<div class="okbox"><div class="ring bad">${ic('x',44)}</div><b>Kaydedilemedi</b><span>${esc(m)}</span>${help?`<div class="msg warn" style="text-align:left;margin-top:8px">${help}</div>`:''}</div>`,`<button class="btn" data-act="close">Kapat</button><button class="btn p" data-act="qrretry">Tekrar dene</button>`)}}
function qrRetry(){const t=ui.lastQr;close();if(t){sessionStorage.setItem('qr',t);doQr()}}
function ackDlg(P){ui.ackP=P;ui.modal=[ackDlg,P];
 dlg('Önce bu duyuruyu okuyun',P.length>1?P.length+' duyuru okundu onayı bekliyor':'Okundu onayı bekleniyor',`${P.map(a=>`<div class="card pad" style="border-left:4px solid var(--warn);margin-bottom:10px"><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px">${a.project_code?pill(['warn',a.project_code+(a.rev_no?' · Rev.'+a.rev_no:'')]):pill(NEWS_K[a.kind]||NEWS_K.genel)}<span class="grow"></span><small style="color:var(--ink3)">${esc(dmy(String(a.created_at).slice(0,10)))}</small></div><h3 style="margin:0 0 6px;font-size:17px">${esc(a.title)}</h3>${a.body?`<div style="white-space:pre-wrap;line-height:1.55">${esc(a.body)}</div>`:''}${newsFile(a,false)}
  <label class="tog" style="margin-top:10px;border-top:1px solid var(--line);padding-top:10px"><span><b>Okudum, anladım</b></span><input type="checkbox" data-ackid="${a.id}"></label></div>`).join('')}<div class="msg info">Okudum, anladım işaretlenince QR girişiniz kaydedilir.</div>`,`<button class="btn" data-act="close">Vazgeç</button><button class="btn p" data-act="ackok">Onayla ve girişi kaydet</button>`,true)}

