/* Weld log: proje kaynak kayıtları (proje birimi). Excel'e aktarılır. */
const WTYPE=[['BW','BW · Alın kaynağı'],['FW','FW · Köşe kaynağı'],['SW','SW · Soket kaynağı'],['BR','BR · Branş bağlantısı'],['TH','TH · Dişli bağlantı']];
