/* İşlem kaydı raporu (genel yönetici): tarih aralığı, kişi, işlem türü; Excel */
const AUD_TR={duyuru:'Duyuru yayınlandı',proje_duyurusu:'Proje revizyonu / duyurusu',proje_kodu:'Proje kodu açıldı',proje_sil:'Proje silindi',proje_listeden_kaldir:'Proje listeden kaldırıldı',proje_geri_al:'Proje geri alındı',firma_ekle:'Firma eklendi',liste_plan_onay:'Planlı liste onaylandı',liste_bos_dfs:'Boştaki personel DFS-26-001\'e yazıldı',kart_basmaz:'Kart basmaz işareti',punch_kontrol_eden:'Punch kontrol eden atandı',punch_ekibi:'Punch kontrol ekibi değişti'};
const audName=a=>AUD_TR[a]||capTr(String(a||'').replace(/_/g,' '));
function auditDlg(){ui.modal=[auditDlg];const f=ui.audf||(ui.audf={from:'',to:'',who:'',q:''}),R=D.audr;
 dlg('İşlem kaydı raporu','Kim, ne zaman, hangi işlemi yaptı',`<div class="two"><label class="f">Başlangıç<input class="inp" type="date" name="au_from" value="${esc(f.from)}"></label><label class="f">Bitiş<input class="inp" type="date" name="au_to" value="${esc(f.to)}"></label>
 <label class="f">Kişi<select class="inp" name="au_who">${opts(S.people.map(p=>[p.id,p.full_name]),f.who,'Herkes')}</select></label><label class="f">İşlem ara<input class="inp" name="au_q" value="${esc(f.q)}" placeholder="Ör. onay, silme, proje"></label></div>
 <div class="tools" style="margin:4px 0 10px"><button class="btn p" data-act="audrun">${ic('eye',16)}Göster</button>${R?`<button class="btn" data-act="audx">${ic('down',16)}Excel</button><span class="pill gray">${R.length} kayıt</span>`:''}</div>
 ${R?`<div class="tw"><table><thead><tr><th>Tarih</th><th>Kişi</th><th>İşlem</th><th>İlgili</th></tr></thead><tbody>${R.slice(0,300).map(a=>`<tr><td style="white-space:nowrap">${esc(dmy(a.at))} ${tm(a.at)}</td><td>${esc(a.actor?nm(a.actor):'Sistem')}</td><td>${esc(audName(a.action))}</td><td>${esc(audTarget(a))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Kayıt yok</td></tr>'}</tbody></table></div>${R.length>300?'<small>İlk 300 kayıt gösteriliyor, tamamı Excel\'de.</small>':''}`:''}`,`<button class="btn p" data-act="close">Kapat</button>`,true)}
const audTarget=a=>{const t=a.target&&pp(a.target)?nm(a.target):(a.target||'');const d=a.detail||{};return[t,d.baslik,d.not,d.adet!=null?d.adet+' adet':''].filter(Boolean).join(' · ')};

